<?php
declare(strict_types=1);
use Karoor\Core\Helpers;
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false||$id===null){http_response_code(404);exit('Receipt not found.');}$companyId=(int)$currentUser['company_id'];$scope=$auth->can('sales.view')?'':' AND s.salesperson_id=:user';$params=['id'=>$id,'company'=>$companyId];if($scope!=='')$params['user']=(int)$currentUser['id'];
$sale=$database->fetchOne('SELECT s.*,c.name customer_name,c.phone customer_phone,w.name warehouse_name,u.full_name cashier_name,co.name company_name,co.phone company_phone,co.email company_email,co.address_line1,co.city,co.tax_number,co.vat_number,co.currency_code,co.logo_path FROM sales s LEFT JOIN customers c ON c.id=s.customer_id INNER JOIN warehouses w ON w.id=s.warehouse_id INNER JOIN users u ON u.id=s.salesperson_id INNER JOIN companies co ON co.id=s.company_id WHERE s.id=:id AND s.company_id=:company AND s.deleted_at IS NULL'.$scope,$params);if($sale===null){http_response_code(404);exit('Receipt not found.');}$items=$database->fetchAll('SELECT product_name,sku,quantity,unit_price,discount_amount,tax_amount,line_total FROM sale_items WHERE sale_id=:id ORDER BY id',['id'=>$id]);$payments=$database->fetchAll('SELECT p.payment_method,p.amount,p.reference_number FROM sale_payments sp INNER JOIN payments p ON p.id=sp.payment_id WHERE sp.sale_id=:id AND p.deleted_at IS NULL ORDER BY p.id',['id'=>$id]);$width=$database->fetchOne('SELECT setting_value FROM settings WHERE company_id=:company AND setting_key=\'receipt.paper_width\'',['company'=>$companyId])['setting_value']??'80';$paper=$width==='58'?'receipt-58':'receipt-80';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt <?= Helpers::escape($sale['invoice_number']) ?></title><link rel="stylesheet" href="<?= Helpers::escape(Helpers::appPath($config,'/assets/css/print.css')) ?>"></head><body class="print-document <?= $paper ?>"><div class="print-toolbar"><button type="button" data-print-trigger>Print receipt</button><a href="<?= Helpers::escape(Helpers::appPath($config,'/sales')) ?>">Back to sales</a></div><main class="receipt"><header class="print-brand"><?php if($sale['logo_path']):?><img src="<?= Helpers::escape(Helpers::appPath($config,'/'.$sale['logo_path'])) ?>" alt=""><?php endif;?><h1><?= Helpers::escape($sale['company_name']) ?></h1><p><?= Helpers::escape(trim(($sale['address_line1']??'').' '.($sale['city']??''))) ?><br><?= Helpers::escape($sale['company_phone']??'') ?></p><?php if($sale['tax_number']):?><p>TIN: <?= Helpers::escape($sale['tax_number']) ?></p><?php endif;?></header><div class="print-meta"><span>Receipt</span><strong><?= Helpers::escape($sale['invoice_number']) ?></strong><span>Date</span><strong><?= Helpers::escape(date('Y-m-d H:i',strtotime($sale['sale_date']))) ?></strong><span>Cashier</span><strong><?= Helpers::escape($sale['cashier_name']) ?></strong><span>Customer</span><strong><?= Helpers::escape($sale['customer_name']??'Walk-in customer') ?></strong></div><table><thead><tr><th>Item</th><th>Qty</th><th class="num">Amount</th></tr></thead><tbody><?php foreach($items as$item):?><tr><td><?= Helpers::escape($item['product_name']) ?><small><?= Helpers::escape($item['sku']) ?> @ <?= number_format((float)$item['unit_price'],2) ?></small></td><td><?= number_format((float)$item['quantity'],2) ?></td><td class="num"><?= number_format((float)$item['line_total'],2) ?></td></tr><?php endforeach;?></tbody></table><dl class="totals"><dt>Subtotal</dt><dd><?= number_format((float)$sale['subtotal'],2) ?></dd><dt>Discount</dt><dd><?= number_format((float)$sale['discount_amount'],2) ?></dd><dt>Tax</dt><dd><?= number_format((float)$sale['tax_amount'],2) ?></dd><dt class="grand">Total <?= Helpers::escape($sale['currency_code']) ?></dt><dd class="grand"><?= number_format((float)$sale['total_amount'],2) ?></dd><dt>Paid</dt><dd><?= number_format((float)$sale['paid_amount'],2) ?></dd><dt>Due</dt><dd><?= number_format((float)$sale['due_amount'],2) ?></dd></dl><?php if($payments):?><section><h2>Payments</h2><?php foreach($payments as$payment):?><p class="payment-row"><span><?= Helpers::escape(str_replace('_',' ',$payment['payment_method'])) ?></span><strong><?= number_format((float)$payment['amount'],2) ?></strong></p><?php endforeach;?></section><?php endif;?><footer>Thank you for your business.</footer></main><script src="<?= Helpers::escape(Helpers::appPath($config,'/assets/js/print.js')) ?>" defer></script></body></html>
